-- Demo customer Hamza M.
INSERT INTO "Customer" ("deviceId", "pickupName")
VALUES ('demo-customer-hamza', 'Hamza M.')
ON CONFLICT ("deviceId") DO UPDATE SET "deviceId" = EXCLUDED."deviceId", "pickupName" = EXCLUDED."pickupName";
WITH inserted AS (
  INSERT INTO "Order" (
    "restaurantId", "customerId", "orderNumber", "orderDate", "status",
    "subtotalCents", "discountCents", "taxCents", "totalCents", "platformFeeCents", "restaurantReceivesCents",
    "appliedDealId", "appliedDealName", "stripePaymentIntentId",
    "createdAt", "acceptedAt", "readyAt", "pickedUpAt", "paidOutAt"
  )
  SELECT 'miso-ember', c."id", 900, (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days'), 'PICKED_UP',
    2800, 560, 199, 2439, 122, 2317,
    'miso-ember-percent-off-25', '20% off orders over $25', 'seed_demo-customer-hamza_0',
    (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days') + interval '1080 minutes', (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days') + interval '1082 minutes', (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days') + interval '1094 minutes', (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days') + interval '1100 minutes', (date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' - interval '3 days') + interval '1100 minutes'
  FROM "Customer" c WHERE c."deviceId" = 'demo-customer-hamza'
  ON CONFLICT ("stripePaymentIntentId") DO NOTHING
  RETURNING "id"
)
